import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel 6353c49:
# packet.Login{ClientProtocol: 1001, ConnectionRequest: []byte("abc")}
LOGIN = bytes.fromhex("000003e903616263")

GOLDENS = [
    pytest.param(
        version.LoginPacket(client_network_version=1001, connection_request=b"abc"),
        LOGIN,
        id=version.__name__.rpartition(".")[2],
    )
    for version in VERSIONS
]


@pytest.mark.parametrize("version", VERSIONS)
def test_login_is_packet_1(version):
    assert version.PACKETS[1] is version.LoginPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_login_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_login_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS)
def test_login_rejects_a_connection_request_shorter_than_its_prefix_claims(version):
    with pytest.raises(ValueError, match="at byte"):
        version.LoginPacket.from_bytes(LOGIN[:-1])
